#!/bin/bash
# Generated by React Native on every `spm add` and `spm update`.
# Do not edit: changes are overwritten.

set -euo pipefail

destination="$TARGET_BUILD_DIR/$FRAMEWORKS_FOLDER_PATH"
mkdir -p "$destination"

validate_framework() {
  source="$1"
  name="$2"
  if [ -z "$source" ] || [ ! -d "$source" ]; then
    echo "error: React Native SwiftPM framework '$name' is unavailable for configuration '$CONFIGURATION' and SDK '$SDK_NAME': $source"
    exit 1
  fi
  binary="${name%.framework}"
  if [ ! -e "$source/$binary" ] && [ ! -e "$source/Versions/Current/$binary" ]; then
    echo "error: React Native SwiftPM framework '$name' is invalid for configuration '$CONFIGURATION': expected $source/$binary or $source/Versions/Current/$binary"
    exit 1
  fi
}

copy_and_sign() {
  source="$1"
  name="$2"
  /usr/bin/rsync -a --delete "$source/" "$destination/$name/"
  if [ "${CODE_SIGNING_ALLOWED:-YES}" != "NO" ]; then
    identity="${EXPANDED_CODE_SIGN_IDENTITY:--}"
    if [ "$identity" = "-" ]; then
      /usr/bin/codesign --force --sign - --timestamp=none --preserve-metadata=identifier,entitlements,flags "$destination/$name"
    else
      /usr/bin/codesign --force --sign "$identity" --preserve-metadata=identifier,entitlements,flags "$destination/$name"
    fi
  fi
}

validate_framework "${RN_SPM_REACT_FRAMEWORK:-}" "React.framework"
validate_framework "${RN_SPM_REACT_NATIVE_DEPENDENCIES_FRAMEWORK:-}" "ReactNativeDependencies.framework"
validate_framework "${RN_SPM_HERMES_FRAMEWORK:-}" "hermesvm.framework"
copy_and_sign "${RN_SPM_REACT_FRAMEWORK:-}" "React.framework"
copy_and_sign "${RN_SPM_REACT_NATIVE_DEPENDENCIES_FRAMEWORK:-}" "ReactNativeDependencies.framework"
copy_and_sign "${RN_SPM_HERMES_FRAMEWORK:-}" "hermesvm.framework"
